import java.util.*;

class Solution {
    public int ladderLength(String beginWord, String endWord, List<String> wordList) {
        Set<String> set = new HashSet<>(wordList);
        if (!set.contains(endWord)) return 0;

        Deque<String> queue = new ArrayDeque<>();
        queue.add(beginWord);
        int level = 1;

        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                String cur = queue.poll();
                if (cur.equals(endWord)) return level;

                Iterator<String> it = set.iterator();
                while (it.hasNext()) {
                    String w = it.next();
                    if (diffOne(cur, w)) {
                        it.remove();
                        queue.add(w);
                    }
                }
            }
            level++;
        }
        return 0;
    }

    private boolean diffOne(String a, String b) {
        if (a.length() != b.length()) return false;
        int diff = 0;
        for (int i = 0; i < a.length(); i++) {
            if (a.charAt(i) != b.charAt(i)) {
                if (++diff > 1) return false;
            }
        }
        return diff == 1;
    }
}

import java.util.*;

class Solution {
    public int ladderLength(String beginWord, String endWord, List<String> wordList) {
        Set<String> words = new HashSet<>(wordList);
        if (!words.contains(endWord)) return 0;
        words.add(beginWord);

        Map<String, List<String>> buckets = new HashMap<>();
        for (String w : words) {
            for (int i = 0; i < w.length(); i++) {
                String key = w.substring(0, i) + "*" + w.substring(i + 1);
                buckets.computeIfAbsent(key, k -> new ArrayList<>()).add(w);
            }
        }

        Set<String> visited = new HashSet<>();
        Deque<String> queue = new ArrayDeque<>();
        visited.add(beginWord);
        queue.add(beginWord);
        int level = 1;

        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                String cur = queue.poll();
                if (cur.equals(endWord)) return level;

                for (int p = 0; p < cur.length(); p++) {
                    String key = cur.substring(0, p) + "*" + cur.substring(p + 1);
                    for (String w : buckets.getOrDefault(key, Collections.emptyList())) {
                        if (visited.add(w)) queue.add(w);
                    }
                }
            }
            level++;
        }
        return 0;
    }
}

import java.util.*;

class Solution {
    public int ladderLength(String beginWord, String endWord, List<String> wordList) {
        Set<String> words = new HashSet<>(wordList);
        if (!words.contains(endWord)) return 0;
        words.add(beginWord);

        Map<String, List<String>> buckets = new HashMap<>();
        for (String w : words) {
            for (int i = 0; i < w.length(); i++) {
                String key = w.substring(0, i) + "*" + w.substring(i + 1);
                buckets.computeIfAbsent(key, k -> new ArrayList<>()).add(w);
            }
        }

        Set<String> front = new HashSet<>();
        Set<String> back = new HashSet<>();
        front.add(beginWord);
        back.add(endWord);
        int level = 1;

        while (!front.isEmpty() && !back.isEmpty()) {
            if (front.size() > back.size()) {
                Set<String> tmp = front;
                front = back;
                back = tmp;
            }

            Set<String> next = new HashSet<>();
            for (String w : front) {
                for (int i = 0; i < w.length(); i++) {
                    String key = w.substring(0, i) + "*" + w.substring(i + 1);
                    for (String nb : buckets.getOrDefault(key, Collections.emptyList())) {
                        if (back.contains(nb)) return level + 1;
                        if (!front.contains(nb)) next.add(nb);
                    }
                }
            }
            front = next;
            level++;
        }
        return 0;
    }
}
